from hermes_tools import terminal
script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)
ws=wb['Task']
wd=wb['Data']
def row_values(ws, row, start=1, end=12):
    return [(get_column_letter(c), ws.cell(row,c).value) for c in range(start,end+1)]
print('\nTask row 10 A:L:')
print(row_values(ws,10,1,12))
print('Task row 10 H:L:', row_values(ws,10,8,12))
for rng in [(12,17),(19,24),(26,31)]:
    print(f'\nTask rows {rng[0]}:{rng[1]} A:L (labels/codes/targets):')
    for r in range(rng[0], rng[1]+1):
        print(r, row_values(ws,r,1,12))
print('\nTask rows 35:40 A:L:')
for r in range(35,41): print(r, row_values(ws,r,1,12))
print('\nTask row 41 A:L:', row_values(ws,41,1,12))
print('\nTask rows 42:47 A:L:')
for r in range(42,48): print(r, row_values(ws,r,1,12))
print('\nTask row 50 A:L:', row_values(ws,50,1,12))
# yellow-ish fills in likely ranges
ranges = [(12,17,8,12),(19,24,8,12),(26,31,8,12),(35,40,8,12),(42,47,8,12),(50,50,8,12)]
print('\nExisting target-range contents and fills:')
for r1,r2,c1,c2 in ranges:
    print(f'Range {get_column_letter(c1)}{r1}:{get_column_letter(c2)}{r2}')
    for r in range(r1,r2+1):
        vals=[]
        for c in range(c1,c2+1):
            cell=ws.cell(r,c)
            vals.append((cell.coordinate, cell.value, cell.fill.fill_type, cell.fill.fgColor.rgb, cell.fill.fgColor.indexed, cell.fill.fgColor.type))
        print(vals)
print('\nData dimensions:', wd.max_row, wd.max_column)
for rr in [20,21]:
    print(f'Data row {rr} A:Z:', row_values(wd,rr,1,min(26,wd.max_column)))
print('\nData sample rows 21:38 A:Z:')
for r in range(21, min(38, wd.max_row)+1):
    print(r, row_values(wd,r,1,min(26,wd.max_column)))
# Identify where Task codes appear in Data
codes=[]
for rng in [(12,17),(19,24),(26,31)]:
    for r in range(rng[0], rng[1]+1):
        codes.append(ws.cell(r,4).value)
print('\nTask codes:', codes)
for col in range(1, min(wd.max_column, 30)+1):
    found=[]
    for r in range(1, wd.max_row+1):
        if wd.cell(r,col).value in codes:
            found.append((r, wd.cell(r,col).value))
    if found:
        print('Codes found in Data col', get_column_letter(col), found[:20])
# Identify years in data rows
for row in range(1, min(wd.max_row,50)+1):
    yrs=[]
    for col in range(1, min(wd.max_column,50)+1):
        v=wd.cell(row,col).value
        if v in [ws.cell(10,c).value for c in range(8,13)]:
            yrs.append((get_column_letter(col), v))
    if yrs:
        print('Task years found in Data row', row, yrs)
'''
res=terminal('python3 - <<\'PY\'\n'+script+'\nPY', timeout=120, workdir='/root')
print(res['output'])
if res['exit_code']:
    print('EXIT', res['exit_code'])
